from pathlib import Path
import json
full=Path('tools/assets/Layout102.cs.txt').read_text(encoding='utf-8-sig');prefix=full.split(' public static string Run()')[0].replace('class Layout102','class Facing102')
code=prefix+r''' public static string Run(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var root=GameObject.Find("Lobby_Island_Visual_Prototype").transform;var main=root.Find("01_Central_Island");foreach(var t in main.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Static_Staff_")).ToArray()){var p=t.parent;var before=V(t).Select(p.InverseTransformPoint).ToArray();var pos=new Vector3((before.Min(q=>q.x)+before.Max(q=>q.x))/2,before.Min(q=>q.y),(before.Min(q=>q.z)+before.Max(q=>q.z))/2);t.localRotation=Quaternion.identity;Fit(t,p,pos,0);var after=V(t).Select(p.InverseTransformPoint).ToArray();report.AppendLine(t.name+" center/base="+pos+" actual height="+(after.Max(q=>q.y)-after.Min(q=>q.y)).ToString("F2"));}var bank=main.Find("Bank_Crystal_Boutique095");Shot(bank.position+new Vector3(2,2.8f,-12),bank.position+new Vector3(0,1.6f,0),8,"51-bank-clerk102");var lab=main.Find("Animal_Laboratory097");Shot(lab.position+new Vector3(8,7,-11),lab.position+Vector3.up*1.5f,8,"52-lab-technician102");var weapon=main.Find("02_Open_Market/03_Guns_Source_Home_GunsStore");Shot(weapon.position+new Vector3(9,8,-13),weapon.position+Vector3.up*1.2f,9,"46-open-armory102");Shot(main.TransformPoint(new Vector3(0,5,-32)),main.TransformPoint(new Vector3(0,1,5)),28,"50-five-market-staff102");File.AppendAllText("Docs/assets/lobby-island/LAYOUT_STAFF102_VALIDATION.txt","\nFacing check: source yaw0 faces visitors (-Z); all5 corrected to native facing.\n"+report.ToString());EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return report.ToString();}
}'''
Path('tools/assets/Facing102.cs.txt').write_text(code,encoding='utf-8');Path('Library/WorkshopBackups/DB-ON-102/facing.json').write_text(json.dumps({'csharpCode':code,'className':'Facing102','methodName':'Run'}),encoding='utf-8')
